The representation of \eqref{eq:S_DA_hybrid} is obvious, thus, we only show the reversibility of $H_t$ defined in \eqref{eq:S_DA_Ht}. 
Let $x\in G$ and $A,B\in\mathcal{B}(G)$. 
Then, using the fact that 
$\mathbb{1}_{G_s,\rhoapp}(x)=\mathbb{1}_{(0,\rhoapp(x))}(s)$ for any $s\in(0,\Vert \rhoapp \Vert_{\infty})$
and setting $c:=1/(Z_{\text{app}}\cdot \pi_{\text{app}}(G_{t, \widehat{\varrho}}))$, where 
\begin{align}\label{normalizing:app}
   Z_{\text{app}} :=\int_G^{} \rhoapp(x)  \, \pi_0(\mathrm{d}x)    
\end{align}
yields
\begin{align*}
	&\int_{A} H_t(x,B)  \, \pi_{\text{app},t}(\mathrm{d}x) = \int_{A} \left( \frac{1}{\rhoapp(x)} \int_{0}^{\rhoapp(x)} \pi_{0,t,s}(B) \mathrm{d}s \right) \frac{\mathbb{1}_{G_{t,\widehat{\varrho}}}(x)}{\pi_{\text{app}}(G_{t, \widehat{\varrho}})}  \, \pi_{\text{app}}(\mathrm{d}x) \\
	&= c \int_{A\cap G_{t,\widehat{\varrho}}} \int_{0}^{\rhoapp(x)} \frac{\pi_0(B \cap G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}})}{\pi_0(G_{s,\rhoapp} \cap G_{t,\widehat{\varrho}})}

	 \, \mathrm{d}s  \, \pi_0(\mathrm{d}x) \\
	&= c  \int_{A\cap G_{t,\widehat{\varrho}}} \int_{B\cap G_{t,\widehat{\varrho}}} \int_{0}^{\infty}  \frac{\mathbb{1}_{(0,\rhoapp(x))}(s) \mathbb{1}_{G_{s,\rhoapp}}(y)}{\pi_0(G_{s,\rhoapp} \cap G_{t,\widehat{\varrho}})}  \, \mathrm{d}s  \, \pi_0(\mathrm{d}y)  \, \pi_0(\mathrm{d}x) \\
	&= c  \int_{A\cap G_{t,\widehat{\varrho}}} \int_{B\cap G_{t,\widehat{\varrho}}} \int_{0}^{\infty}  \frac{\mathbb{1}_{G_s,\rhoapp}(x) \mathbb{1}_{G_{s,\rhoapp}}(y)}{\pi_0(G_{s,\rhoapp} \cap G_{t,\widehat{\varrho}})}  \, \mathrm{d}s  \, \pi_0(\mathrm{d}y)  \, \pi_0(\mathrm{d}x).
\end{align*}
Interchanging the two outer integrals and arguing by the same steps (with $x$ taking the role of $y$) backwards gives the desired reversibility, i.e. 
 \begin{align*}
        \int_{A} H_t(x,B)  \, \pi_{\text{app},t}(\mathrm{d}x)=\int_{B} H_t(y,A)  \, \pi_{\text{app},t}(\mathrm{d}y), \qquad A,B\in\mathcal{B}(G).
    \end{align*}
An immediate consequence is the $\pi$-reversibility of $S_{DA}$. Therefore, let $x\in G$ as well as $A,B\in\mathcal{B}(G)$ and set $\tilde{c}:=Z^{-1} \, Z^{-1}_{\text{app}} \, \pi_{\text{app}}(G_{t,\widehat{\varrho}})$. Then       
 \begin{align*}
        \int_{A} S_{DA}(x,B) \, \pi(\mathrm{d}x)&= \int_{A} \left(\frac{1}{\widehat{\varrho}(x)} \int_{0}^{\widehat{\varrho}(x)} H_t(x,B) \mathrm{d}t \right) \, Z^{-1} \, Z^{-1}_{\text{app}} \, \widehat{\varrho}(x) \, \pi_{\text{app}}(\mathrm{d}x) \\ 
        &=Z^{-1} \, Z^{-1}_{\text{app}}\int_{A} \int_0^\infty H_t(x,B) \mathbb{1}_{G_{t,\widehat{\varrho}}}(x) \frac{\pi_{\text{app}}(G_{t,\widehat{\varrho}})}{\pi_{\text{app}}(G_{t,\widehat{\varrho}})} \, \mathrm{d}t \, \pi_{\text{app}}(\mathrm{d}x) \\
        &= \tilde{c} \int_0^\infty \int_{A} H_t(x,B) \, \pi_{\text{app},t}(\mathrm{d}x) \, \mathrm{d}t \\
        &= \tilde{c} \int_0^\infty \int_{B} H_t(y,A) \, \pi_{\text{app},t}(\mathrm{d}y) \, \mathrm{d}t.
 \end{align*}
 Again, arguing by the same steps backwards (with $y$ instead of $x$) gives the desired result.  
