\label{app:DASS_convergence}





















In order to show the ergodicity of delayed acceptance slice sampling, we need to verify the assumptions of Proposition \ref{Schaer:Convergence}.
To this end, we state the following auxilliary result.

\begin{proposition}\label{positive:measure:iff}
    Let $\pi$ be a probability measure given by (\ref{PMLR:distribution}) and $A\in\mathcal{B}(G)$. Then 
    $\pi(A)>0$ iff there exists $0<S_A\leq \|\rhoapp\|_\infty$ and $0 < T_A \leq \|\widehat{\varrho}\|_\infty$ with $\rhoapp, \widehat{\varrho}$ as in \eqref{PMLR:factorization} such that
    \begin{align*}

        \pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}) > 0, \qquad  \forall s\in(0, S_A) \ \forall t\in(0, T_A).   
    \end{align*}

\end{proposition}

\begin{proof}
    Let $x\in G$ and $A\in\mathcal{B}(G)$. We rewrite the density $\varrho$ in the following form:
    \begin{align*}
        \varrho(x)  = \widehat{\varrho}(x)  \rhoapp(x) & = \int_0^{\infty} \int_0^{\infty} \mathbb{1}_{(0,\varrho_{\textmd{app}(x)})}(s) \mathbb{1}_{(0,\widehat{\varrho}(x))}(t)  \,  \mathrm{d}s  \, \mathrm{d}t\\
        & = \int_0^{\infty} \int_0^{\infty} \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}}(x)  \, \mathrm{d}s  \, \mathrm{d}t
    \end{align*}
    This leads combined with Fubini's theorem to
    \begin{align}
        \pi(A)  = \frac {1}{Z} \, \int_A \varrho(x) \, \pi_0(\mathrm{d}x) & = \frac {1}{Z} \int_0^{\infty} \int_0^{\infty}  \int_A \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}}(x) \, \pi_0(\mathrm{d}x)  \, \mathrm{d}s  \, \mathrm{d}t \notag \\
        & = \frac {1}{Z} \int_0^{\infty} \int_0^{\infty} \pi_0(A \cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})  \, \mathrm{d}s  \, \mathrm{d}t \label{eq:pi}
    \end{align}
    Since $Z>0$ we can conclude that $\pi(A)>0$ if and only if the double integral on the right-hand side is also positive. Define now
    \begin{align*}
       f: (0,\infty)\times(0,\infty) \rightarrow \mathbb R, \quad (t,s) \mapsto \pi_0(A \cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})    
    \end{align*}
    and notice, that the mapping $f$ is non-increasing since whenever $(t_1,s_1)<(t_2,s_2)$ we have $G_{s_2, \varrho_{\textmd{app}}}\cap G_{t_2, \widehat{\varrho}}\subseteq G_{s_1, \varrho_{\textmd{app}}}\cap G_{t_1, \widehat{\varrho}}$. This leads to the fact that $\pi(A)>0$ if and only if there exist an $S_A>0$ and an $T_A>0$ such that $\pi_0(A \cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})>0$ for all $s\in(0, S_A)$ and $t\in(0, T_A)$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{DASS:Ergodicity}]
It follows from Proposition~\ref{PMLR:prop:hybrid} that \(S_{DA}\) is \(\pi\)-reversible and therefore \(\pi\)-invariant. 
It remains to show \eqref{eq:ergodic:abscon1} and \eqref{eq:ergodic:abscon2} for $S_{DA}$, since then by Proposition \ref{Schaer:Convergence} the statement follows.
To this end, let $x\in G$ and $A\in\mathcal{B}(G)$ be arbitrary in the following. 

If $\pi(A) = 0$, then also $\pi_0(A)=0$ by \eqref{PMLR:distribution} and, thus, $\pi_0(A \cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})=0$ for all $(t,s)\in (0,\widehat\varrho(x))\times(0,\rhoapp(x))$.
Hence, we also have $S_{DA}(x,A) = 0$.

Let now $\pi(A)>0$. By Proposition~\ref{positive:measure:iff} there exists $0<S_A\leq \|\rhoapp\|_\infty$ and $0<T_A\leq \|\widehat{\varrho}\|_\infty$, such that $\pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}) > 0$ for all $s\in(0, S_A)$ and $t\in(0, T_A)$. Thus, for $x\in G$ exist $S_{x,A}\in(0, \rhoapp(x)]$ and $T_{x,A}\in(0, \widehat{\varrho}(x)]$ for which by Assumption \ref{assum:positivity_condition} we can conclude that $\pi_{0,t,s}(A)>0$ for all $s\in(0, S_{x,A})$ and $t\in(0, T_{x,A})$. 
Hence, 
\begin{align*}
	S_{DA}(x,A) 
    & = 
    \frac{1}{\varrho(x)}\int_0^{\widehat{\varrho}(x)} \int_0^{\rhoapp(x)} \pi_{0,t,s}(A)  \, \mathrm{d}s  \, \mathrm{d}t\\
    & \geq \frac{1}{\varrho(x)}\int_0^{T_{x,A}} \int_0^{S_{x,A}} \pi_{0,t,s}(A)  \, \mathrm{d}s  \, \mathrm{d}t
    > 0
\end{align*}
as desired. 
\end{proof}

\label{Apendix:Comparison}
We show the statement of Theorem \ref{PMLR:theorem:comparison} by applying a general comparison result of \citet[Lemma~1]{RudolfUllrich2018}. For convenience of the reader, we state the corresponding statement in its abstract form and then verify its assumptions in the setting of Theorem~\ref{PMLR:theorem:comparison}.



Additionally to the measurable space $(G,\mathcal{B}(G))$ let $(I,\mathcal{I},\lambda)$ be a $\sigma$-finite measure space and assume that: 

\begin{itemize}
	\item[{(a)}] 
	There is a function $p\colon G\times I\rightarrow [0,\infty]$ such that $p(x,\cdot)$ is a probability density function w.r.t. $\lambda$ for all $x\in G$ and $p(\cdot,a)$ is integrable w.r.t. $\pi$ for all $a\in I$.
	\item[{(b)}]  
	For every $a\in I$, we have an equivalence relation $\sim_a$ on $G$. We denote the equivalence class of $x\in G$ w.r.t. $\sim_a$ by $[x]_a:=\{y\in G: x \sim_a y\}$.
	\item[{(c)}] 
	For ($\lambda$-almost) every $a\in I$, there exists a transition kernel $P_a$ on $(G, \mathcal{B}(G))$ such that $P_a(x,A)=0$ for each $x\in G$ and $A\in \mathcal{B}(G)$ satisfying $A \subseteq G\setminus [x]_a$. 
\end{itemize}
Moreover, we define for almost all $a\in I$ a probability measure $\pi_{{a}}$ on $G$ by
\begin{align*}
	\pi_a(A):=\frac{\int_{A}p(x,a) \,\pi(\mathrm{d}x)}{\int_{{G}}p(x,a) \,\pi(\mathrm{d}x)}, \quad A\in\mathcal{B}(G).
\end{align*} 


\begin{lemma}[\citet{RudolfUllrich2018}]\label{PMLR:lemma:comparison}
	Assume that for ($\lambda$-almost) all $a\in I$, there are transition kernels $P^{(1)}_a$, $P^{(2)}_a$ on $G$ such that
	\begin{enumerate}
		\item $P^{(1)}_a$ and $P^{(2)}_a$ are self-adjoint operators on $L^2_{\pi_{a}}(G)$;
		\label{en1}
		\item $P^{(1)}_a$ is positive on $L^2_{\pi_{a}}(G)$;
		\item $P^{(1)}_aP^{(2)}_a=P^{(2)}_a$. 
		\label{en3}
	\end{enumerate}
	Then, for the operators $P_1, P_2\colon L^2_{\pi}(G) \rightarrow L^2_{\pi}(G)$ defined by
	\begin{equation*}
		P_if(x)=\int_{I} P^{(i)}_a f(x) p(x,a) \,\lambda(\mathrm{d}a), \qquad i=1,2,
	\end{equation*}
	it follows $P_1\leq P_2$.  
\end{lemma}


\begin{proof}[Proof of Theorem \ref{PMLR:theorem:comparison}]
	We now apply Lemma \ref{PMLR:lemma:comparison} to the setting of Theorem \ref{PMLR:theorem:comparison}.
	To this end, let $I:=(0,\infty)\times(0,\infty)$ and $\lambda:=\lambda_2$ be the two-dimensional Lebesgue measure. 
	We define the function $p\colon G\times I \rightarrow [0,\infty)$ by
	\begin{align*}
		p(x,a):=\frac{1}{\varrho(x)}\mathbb{1}_{(0,\varrho_{\textmd{app}}(x))}(s)\mathbb{1}_{(0,\widehat{\varrho}(x))}(t)
	\end{align*}
	with $a=(s,t)$, which satisfies assumption (a) from above. For every $a=(s,t)\in I$, let $x \sim_a y$ if and only if $x,y\in G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}$, such that $[x]_{a}:=G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}$. This leads to
	\begin{align*}
		\pi_{a}(A)=\frac{\pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})}{\pi_0(G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})}, \quad A\in\mathcal{B}(G).
	\end{align*} 
	For $x\in G$ and $A\in \mathcal{B}(G)$ we set 




	$ S_{DA_{{a}}}(x,A):=\pi_{{a}}(A)$.

	This is clearly a transition kernel that satisfies assumption (c) above. 
	Moreover, the Markov operator $S_{DA}: L^2_{\pi}(G) \rightarrow L^2_{\pi}(G)$ of the delayed acceptance slice sampler can be represented by
	\begin{align*}
		S_{DA}f(x) 
		&=\frac{1}{\varrho(x)} \int_0^{\widehat{\varrho}(x)} \int_0^{\rhoapp(x)} \int_G^{} f(y) \frac{\mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(y)}{\pi_0(G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})}  \, \pi_{0}(\mathrm{d}y)  \, \mathrm{d}s  \, \mathrm{d}t \\
		&= \int_I \int_G f(y)  S_{DA_{{a}}}(x,\mathrm{d}y) \frac{1}{\varrho(x)}\mathbb{1}_{(0,\varrho_{\textmd{app}(x)})}(s) \ \mathbb{1}_{(0,\widehat{\varrho}(x))}(t)  \, \mathrm{d}s  \, \mathrm{d}t \\ 
		&= \int_I S_{DA_{{a}}}  f(x)  p(x,{a}) \,\lambda_2(\mathrm{d}{a}).
	\end{align*}
	We also set  
	\begin{align*}
		M_{DA_{{a}}}(x,A)=  Q(x, A  \cap  G_{s,\rhoapp}  \cap  G_{t,\widehat{\varrho}}) +(1- Q(x, G_{s,\rhoapp}  \cap  G_{t,\widehat{\varrho}})) \cdot \delta_x(A)   
	\end{align*}
	and note that assumption (c) from above is satisfied for this transition kernel.
	Using
	\begin{align*}
		\int_0^{\widehat{\varrho}(x)} \int_0^{\rhoapp(x)} \mathbb{1}_{(0,\varrho_{\textmd{app}}(y))}(s) \, \mathbb{1}_{(0,\widehat{\varrho}(y))}(t)  \, \mathrm{d}s  \, \mathrm{d}t 
		& = \min\{\rhoapp(x),\rhoapp(y)\} \, \min\{\widehat{\varrho}(x), \widehat{\varrho}(y)\}       
	\end{align*}
	yields
	\begin{align*}
		M_{DA}f(x)& = \int_G f(y) \widetilde{\alpha}(x,y)  \, Q(x,\mathrm{d}y) +f(x)\left(1-\int_{G} \widetilde{\alpha}(x,y)  \, Q(x,\mathrm{d}y)\right)\\
		&= \frac{1}{\varrho(x)} \int_0^{\widehat{\varrho}(x)} \int_0^{\rhoapp(x)} \int_G f(y)  \mathbb{1}_{(0,\varrho_{\textmd{app}}(y))}(s)\ \mathbb{1}_{(0,\widehat{\varrho}(y))}(t)  \, Q(x, \mathrm{d}y)  \, \mathrm{d}s  \, \mathrm{d}t \\ 
		&\qquad	+  \frac{f(x)}{\varrho(x)} \int_0^{\widehat{\varrho}(x)} \int_0^{\rhoapp(x)} \int_G  \left(1- \mathbb{1}_{(0,\varrho_{\textmd{app}}(y))}(s)\ \mathbb{1}_{(0,\widehat{\varrho}(y))}(t)\right)  \, Q(x, \mathrm{d}y)  \, \mathrm{d}s  \, \mathrm{d}t\\	


		&= \int_I \int_G f(y)  M_{DA_{{a}}}(x,\mathrm{d}y) \ \frac{1}{\varrho(x)}\mathbb{1}_{(0,\varrho_{\textmd{app}(x)})}(s)\ \mathbb{1}_{(0,\widehat{\varrho}(x))}(t)  \, \mathrm{d}s  \, \mathrm{d}t \\ 
		&= \int_I   M_{DA_{{a}}}f(x) p(x,{a}) \,\lambda_2(\mathrm{d}{a}).
	\end{align*}
	Now we verify \ref{en1}.-\ref{en3}. of Lemma~\ref{PMLR:lemma:comparison} with $P_a^{(1)}=M_{DA_{{a}}}$ and $P_a^{(2)}=S_{DA_{{a}}}$, such that the application of it gives the statement of Theorem~\ref{PMLR:theorem:comparison}. We have:

	\begin{enumerate}
		\item
		\emph{Self-adjointness of $S_{DA_{{a}}}$ and $M_{DA_{{a}}}$ w.r.t.\phantom{.}$\pi_{{a}}$}: It is sufficient to show the $\pi_{{a}}$-reversibility of the transition kernels $S_{DA_{{a}}}$ and $M_{DA_{{a}}}$. 
		For $S_{DA_{{a}}}$ it is obvious due to the relation $S_{DA_{{a}}}(x,A)=\pi_{{a}}(A)$. 
		For proving the reversibility of $M_{DA_{{a}}}$ 
		let $A,B \in \mathcal{B}(G)$ with $A\cap B=\emptyset$.






		We set $c:=1/\pi_0(G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}})$ and obtain
		\begin{align*}
			&	\int_{A}^{} M_{DA_{{a}}}(x,B)  \, \pi_{{a}}(\mathrm{d}x) 
			= \int_{A} Q(x, B  \cap  G_{s,\rhoapp}  \cap  G_{t,\widehat{\varrho}})  \, \pi_{{a}}(\mathrm{d} x) \\
			& = c \int_{G} \int_{G} \mathbb{1}_B(y)  \ \mathbb{1}_{G_{s,\rhoapp}\cap G_{t,\widehat{\varrho}}}(y)\ \mathbb{1}_A(x) \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x)  \,  Q(x,\mathrm{d}y) \, \pi_{0}(\mathrm{d}x) \\
			& = c \int_{G} \int_{G} \mathbb{1}_B(y)  \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}}(y) \ \mathbb{1}_A(x) \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x)  \, Q(y,\mathrm{d}x)  \, \pi_{0}(\mathrm{d}y) \\
			& = \int_{B}^{} M_{DA_{{a}}}(y,A)  \, \pi_{{a}}(\mathrm{d}y),
		\end{align*}
		where the last equality follows due to the reversibility of $Q$ w.r.t. $\pi_0$. 
		This implies by standard arguments the claimed $\pi_a$-reversibility of $M_{DA_a}$.
		\item
		\emph{Positivity of $M_{DA_{{a}}}$ on $L^2_{\pi_a}(G)$}: For any $f\in L^2_{\pi_a}(G)$ we show $\langle M_{DA_{{a}}}f, f \rangle_{\pi_{{a}}}\geq 0$.
		With $a=(s,t)\in I$ we have 
		\begin{align*}
			  \langle M_{DA_{{a}}}f, f \rangle_{\pi_{{a}}}
			& = \int_{[x]_{a}} \int_{[x]_{a}} f(y)  \, M_{DA_{{a}}}(x, \mathrm{d}y)  f(x)  \,  \pi_{{a}}(\mathrm{d}x) \\
			& = \int_{[x]_{a}}^{} \int_{[x]_{a}}^{} f(y) \mathbb{1}_{G_{s,\rhoapp}  \cap  G_{t,\widehat{\varrho}}}(y)  \, Q(x,\mathrm{d}y) f(x)  \, \pi_{{a}}(\mathrm{d}x) \\

			& \qquad + \int_{[x]_{a}}^{} (1-Q(x, G_{s,\rhoapp}  \cap  G_{t,\widehat{\varrho}})) f(x)^2 \,  \pi_{{a}}(\mathrm{d}x).


		\end{align*} 
		We can write the first term in the sum as
		\begin{align*}
			&\int_{[x]_{a}}^{} \int_{[x]_{a}}^{} f(y) f(x) \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(y)  \, Q(x,\mathrm{d}y)  \, \pi_{{a}}(\mathrm{d}x) \\
			&\quad = c \int_{G}^{} \int_{G}^{} f(y) f(x) \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(y)\ \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x)  \, Q(x,\mathrm{d}y)  \, \pi_0(\mathrm{d}x) \\ 


			&\quad= c \, \langle Q\mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}f, \mathbb{1}_{G_{s, \varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}f \rangle_{\pi_0}. 
		\end{align*}
		Finally, by the positivity of $Q$ on $L^2_{\pi_0}(G)$ we get
		\begin{align*}
			\langle M_{DA_{{a}}}f, f \rangle_{\pi_{{a}}}  
			& = c \, \langle Q\mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}f, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}f \rangle_{\pi_0} \\
            & \qquad +\int_{[x]_{a}} (1-Q(x, G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}})) f(x)^2  \, \pi_{{a}}(\mathrm{d}x) 
			\geq 0. 
		\end{align*}
		\item \emph{$M_{DA_{{a}}} S_{DA_{{a}}}=S_{DA_{{a}}}$}: We have
		\begin{align*}
			M_{DA_{{a}}} S_{DA_{{a}}}f(x)
			&=\int_{[x]_{a}}^{}\int_{[x]_{a}}^{} f(y)  \,  S_{DA_{{a}}}(z, \mathrm{d}y)  \,  M_{DA_{{a}}}(x, \mathrm{d}z) \\  
			&=\int_{[x]_{a}}^{}\int_{[x]_{a}}^{} f(y)  \,  \pi_a(\mathrm{d}y)  \,  M_{DA_{{a}}}(x, \mathrm{d}z) \\ 
			&=\int_{[x]_{a}} 

			M_{DA_{{a}}}(x, [x]_{a})
			f(y)  \, \pi_a(\mathrm{d}y) \\ 
			&=\int_{[x]_{a}}^{} f(y)  \,  S_{DA_{{a}}}(x, \mathrm{d}y)
			= S_{DA_{{a}}}f(x). 
		\end{align*}
	\end{enumerate}
	As a direct conclusion of Lemma \ref{PMLR:lemma:comparison}, we have shown the statement.  
\end{proof}

\label{app:DAHSS:reversible}
Let $x\in G$ and $A,B\in\mathcal{B}(G)$. Then with $Z$ defined as in (\ref{PMLR:distribution}) we get 
\begin{align*}
	&\int_{A} H_{{DA}}(x,B)  \, \pi(\mathrm{d}x)
	= \int_{A} \left( \frac{1}{\varrho(x)} \int_{0}^{\widehat{\varrho}(x)} \int_{0}^{\rhoapp(x)} H_{t,s}(x, B)  \, \mathrm{d}s  \, \mathrm{d}t \right) Z^{-1} \varrho(x)  \, \pi_0(\mathrm{d}x) \\
	&= Z^{-1}  \int_{A} \int_{0}^{\infty} \int_{0}^{\infty} H_{t,s}(x, B) \mathbb{1}_{G_{s,\rhoapp}}(x) \mathbb{1}_{G_{t,\widehat{\varrho}}}(x) \frac{\pi_0(G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}})}{\pi_0(G_{s,\rhoapp} \cap G_{t,\widehat{\varrho}})}

	 \,\mathrm{d}s  \, \mathrm{d}t  \, \pi_0(\mathrm{d}x) \\
	&= Z^{-1}  \int_{0}^{\infty} \int_{0}^{\infty} \pi_0(G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}}) \int_{A} H_{t,s}(x, B)  \, \pi_{0,t,s} (\mathrm{d}x)  \, \mathrm{d}s  \, \mathrm{d}t  \\
	&= Z^{-1}  \int_{0}^{\infty} \int_{0}^{\infty} \pi_0(G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}}) \int_{B} H_{t,s}(y, A)  \,  \pi_{0,t,s} (\mathrm{d}y)  \, \mathrm{d}s  \, \mathrm{d}t.
\end{align*}
The last equality follows from the fact that $H_{t,s}$ is $\pi_{0,t,s}$-reversible. Arguing by the same steps (with $x$ taking the role of $y$) backwards gives the desired reversibility, i.e. 
 \begin{align*}
        \int_{A} H_{{DA}}(x,B)  \, \pi(\mathrm{d}x)=\int_{B} H_{{DA}}(y,A)  \, \pi(\mathrm{d}y), \qquad A,B\in\mathcal{B}(G).
    \end{align*}
For the second part of the proof, showing the $\pi$-invariance of $H_{{DA}}$, we can conclude analogously with some steps before that  
\begin{align*}
    \pi H_{DA}(A)&= \int_{G} H_{{DA}}(x,A) \, \pi(\mathrm{d}x) \\
                 &= Z^{-1}  \int_{0}^{\infty} \int_{0}^{\infty} \pi_0(G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}}) \int_{G} H_{t,s}(x, A)  \,  \pi_{0,t,s} (\mathrm{d}x)  \, \mathrm{d}s  \, \mathrm{d}t \\
                 &=  Z^{-1}  \int_{0}^{\infty} \int_{0}^{\infty} \pi_0(G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}}) \, \pi_{0,t,s} (A)  \, \mathrm{d}s  \, \mathrm{d}t \\
                 &=  Z^{-1} \int_{0}^{\infty} \int_{0}^{\infty} \pi_0(A \cap G_{s,\rhoapp} \cap  G_{t,\widehat{\varrho}}) \, \mathrm{d}s  \, \mathrm{d}t = \pi(A).    
\end{align*}
Here, the third equality follows from the fact that $H_{t,s}$ is $\pi_{0,t,s}$-invariant and the last equality due to (\ref{eq:pi}) from the proof of Proposition \ref{positive:measure:iff}.  
\begin{flushright}    
$\square$
\end{flushright}

\label{app:DAESS}

The on-slice transition kernels of DA-ESS \change{(Algorithm \ref{alg:DAESS})} for $x\in G$, $A\in\mathcal{B}(G)$, $s \in (0, \rhoapp(x))$ and $t \in (0, \widehat{\varrho}(x))$ take the form 
\[
   E_{t,s}(x,A):=\int_{\mathbb R^d} E_{x,v,t,s}(A) \, \pi_0(\mathrm{d} v)
\]
where $E_{x,v,t,s}$ represents the transition mechanism for moving to a set $A\in\mathcal{B}(G)$ using the delayed acceptance shrinkage routine in Algorithm \ref{alg:DA-Shrinkage} given  $x, v, t$ and $s$. 
\change{Since the delayed acceptance routine accepts a proposal if and only if it belongs to $G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}$ and otherwise applies exactly the same shrinkage update as the plain ESS shrinkage routine, the resulting on-slice transition coincides with the ESS transition on the intersection $G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}$. Hence, applying} the proof in \citet[Theorem~3.1]{HasenpflugEtAl2023} to the delayed acceptance scheme also yields the \change{$\pi_{0,t,s}$}-reversibility of $E_{t,s}$ in that setting \change{and therefore, by Proposition~\ref{prop:DAHSS:reversible}, the desired result.} 

In the following, let $x\in G$ and $A\in\mathcal{B}(G)$ be arbitrary. To prove \change{ergodicity}, we verify that Assumption \ref{statement1}. \change{and \ref{statement2}} of Proposition \ref{prop:DAHSS:ergodic} holds. 

\begin{enumerate}

    \item  
    Let $\pi(A)>0$, then an immediate consequence of Proposition~\ref{positive:measure:iff} is that there exist $S_{x,A}\in(0, \rhoapp(x)]$ and $T_{x,A}\in(0, \widehat{\varrho}(x)]$, such that $\pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}) > 0$ for all $s\in(0, S_{x,A})$ and $t\in(0, T_{x,A})$. To show \change{that} $E_{t,s}(x,A)>0$ for all $s\in(0, S_{x,A})$ and $t\in(0, T_{x,A})$, note that the probability of moving to a set $A\in\mathcal{B}(G)$ after completing all steps in lines 2-5 of Algorithm \ref{alg:DAESS} is greater than or equal to the 
    probability \change{that the first angle proposal is accepted and the resulting state belongs to $A$.}
    Hence, this leads, together with \change{Tonelli’s theorem}, to   
    \[
       E_{t,s}(x,A)\geq \frac{1}{2\pi}\int_{-\pi}^{\pi}\int_{\mathbb R^d} \mathbb{1}_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(p(x,v,\theta)) \, \pi_0(\mathrm{d} v) \, \mathrm{d}\theta. 
    \]
    In the following, we show that the right-hand side of the inequality is positive. We define for $\theta_0\in(-\pi,\pi)\setminus\{0\}$ the linear mapping
    \begin{align*}
       T_{x,\theta_0}: \mathbb R^d \rightarrow \mathbb R^d, \quad v \mapsto p(x, v, \theta_0)=\cos(\theta_0) \ x + \sin(\theta_0)\ v.    
    \end{align*}
    The mapping $T_{x,\theta_0}$ is bijective and its preimage is given by 
    \begin{align}\label{inverse:mapping}
       T_{x,\theta_0}^{-1}(A)=\{v\in\mathbb R^d\colon T_{x,\theta_0}(v)\in A\}.
    \end{align}
    Consequently we get for all $\theta_0\in(-\pi,\pi)\setminus\{0\}$, $s\in(0, S_{x,A})$ and $t\in(0, T_{x,A})$   
    \begin{align*}
        \int_{\mathbb R^d} \mathbb{1}_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(p(x,v,\theta_0)) \, \pi_0(\mathrm{d} v)&=\pi_0(\{v\in\mathbb R^d\colon p(x, v, \theta_0)\in A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}\}) \\
        &=\pi_0(\{v\in\mathbb R^d\colon T_{x,\theta_0}(v)\in A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}\}) \\
        &= \pi_0(T_{x,\theta_0}^{-1}( A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}})) >0,
    \end{align*}
    where the positivity follows from the change-of-variables theorem and the well-known fact, that in finite dimensions, a non-degenerate Gaussian measure is equivalent to the Lebesgue measure. Therefore, we can conclude that for all $s\in(0, S_{x,A})$ and all $t\in(0, T_{x,A})$
    \begin{align*}
        E_{t,s}(x,A)&\geq \frac{1}{2\pi}\int_{(-\pi,\pi)\setminus\{0\}} \int_{\mathbb R^d} \mathbb{1}_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(p(x,v,\theta)) \, \pi_0(\mathrm{d} v) \, \mathrm{d}\theta > 0 

    \end{align*}

    \item 
    \change{If $\pi(A)=0$, then also $\pi_0(A)=0$ by (\ref{PMLR:distribution}) and $\lambda_d(A)=0$ since the Gaussian prior measure and the Lebesgue measure are equivalent. The delayed acceptance shrinkage routine terminates when it generates an angle in the set $\Theta_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)$ as defined in \eqref{eq:theta_B_def}. To describe those accepted points which additionally belong to $A$, we consider $\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)$. We first show that $\lambda_1(\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))=0$ for $\pi_0$-almost every $v\in\mathbb R^d$. Since $A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}\subseteq A$ we have $\lambda_d(A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}})=0$ and therefore as above
    \[
      \int_{\mathbb R^d} \mathbb{1}_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(p(x,v,\theta_0)) \, \pi_0(\mathrm{d} v) = \pi_0(T_{x,\theta_0}^{-1}( A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}})) = 0,
    \]
    with $T_{x,\theta_0}^{-1}$ given as in \eqref{inverse:mapping}, for every $\theta_0\in(-\pi,\pi)\setminus\{0\}$. Notice, that $\{-\pi,0,\pi\}$ has one-dimensional Lebesgue measure zero. This leads together with Tonelli to
    \begin{align*}
    0 

    &=\int_{\mathbb R^d} \int_{-\pi}^{\pi} \mathbb{1}_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(p(x,v,\theta)) \, \mathrm{d}\theta  \, \pi_0(\mathrm{d} v)\\
    &= \int_{\mathbb R^d} \lambda_1(\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)) \, \pi_0(\mathrm{d} v),
    \end{align*}
    which implies $\lambda_1(\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))=0$ for $\pi_0$-almost every $v\in \mathbb R^d$. Arbitrarily fix from now on such a $v\in \mathbb R^d$. As in \citet{HasenpflugEtAl2023}, consider the unstopped sequence corresponding to the delayed acceptance shrinkage routine in Algorithm~\ref{alg:DA-Shrinkage}, and let $\Theta_1, \Theta_2, \dots$, denote its successive angle proposals. 

    The first proposal angle is generated before any shrinkage takes place and satisfies $\Theta_1\sim \mathrm{U}(-\pi,\pi)$. Hence,
    \begin{align*}
        \mathbb P\left(\Theta_1\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\right)= \frac{\lambda_1\left(\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\right)}{2\pi}=0.
    \end{align*}
    For $k\geq 2$, let $\Theta^{\min}_k$ and $\Theta^{\max}_k$ denote the current shrinkage interval bounds immediately before the $k$-th angle proposal is generated. By construction of Algorithm~\ref{alg:DA-Shrinkage}, conditional on these bounds, the $k$-th proposal is uniformly distributed on $I_k=(\Theta^{\min}_k, \Theta^{\max}_k)$, cf. \citet[Equation~(4)]{HasenpflugEtAl2023}. Therefore, 
    \begin{align*}
        \mathbb{P}(\Theta_k\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\mid I_k)= \frac{\lambda_1\left(\Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\cap I_k \right)}{\lambda_1\left(I_k\right)}=0.
    \end{align*}
    By the tower property we get  
    \begin{align*}
       \mathbb P(\Theta_k\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))=\mathbb E\left[\mathbb{P}(\Theta_k\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\mid I_k)\right]=0.   
    \end{align*}
    Now, define the stopping time by $\tau_{t,s}:=\inf\{k\geq 1: \Theta_k \in \Theta_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\}$, which is the first index for which $p(x,v, \Theta_k)\in G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}$. Since $\rhoapp$ and $\widehat{\varrho}$ are lower semi-continuous, $G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}$ is open and since $\theta\mapsto p(x,v,\theta)$ is continuous, we get that $\Theta_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)$ is open on the circle.
    Moreover, the set is non-empty since $0\in\Theta_{G_{s,\rhoapp}\cap G_{t,\widehat{\varrho}}}(x,v)$.
    Thus, by \citet[Lemma~2.7]{HasenpflugEtAl2023} we have $\tau_{t,s}<\infty$ almost surely. Since $\{\tau_{t,s}<\infty\}=\cup^\infty_{k=1}\{\tau_{t,s}=k\}$, where the events are pairwise disjoint, we obtain 
    \begin{align*}
        E_{x,v,t,s}(A)&=\mathbb{P}(\Theta_{\tau_{t,s}}\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v), \tau_{t,s}<\infty) \\
        &=\sum_{k=1}^\infty \mathbb{P}(\Theta_{\tau_{t,s}}\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v), \tau_{t,s}=k) \\
        &=\sum_{k=1}^\infty \mathbb{P}(\Theta_{k}\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v), \tau_{t,s}=k) \\
        &\leq \sum_{k=1}^\infty \mathbb P(\Theta_k\in \Theta_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)) = 0.
    \end{align*}
    Hence, 
    \[
    E_{t,s}(x,A):=\int_{\mathbb R^d} E_{x,v,t,s}(A) \, \pi_0(\mathrm{d} v)=0
    \]
    for all $t\in(0,\widehat{\varrho}(x))$ and all $s\in(0, \rhoapp(x))$.
    }

\end{enumerate}

\begin{flushright}    
$\square$
\end{flushright}

\label{app:DAHRUSS}

The on-slice transition kernels of DA-HRUSS for $x\in G$, $A\in\mathcal{B}(G)$, $s \in (0, \rhoapp(x))$ and $t \in (0, \widehat{\varrho}(x))$, \change{underlying Algorithm \ref{alg:DAHRSS} under Assumption \ref{assum:bimodal} and \eqref{eq:line_section_def}}, take the form 
\begin{align*}
    R_{t,s}(x,A)&=\int_{\mathbb{S}_{d-1}} \change{\Biggl[}  \xi_{t,s}(x,v) \, \frac{\lambda_1(L_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))}  {\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))} \\
    &\qquad+ (1-\xi_{t,s}(x,v)) \sum_{i=1}^2 \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G^{(i)}_{t,\widehat{\varrho}}}(x) \,  \frac{\lambda_1(L_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G^{(i)}_{t,\widehat{\varrho}}}(x,v))}  {\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G^{(i)}_{t,\widehat{\varrho}}}(x,v))} \change{\Biggr]}  \, \frac{\sigma_d(\mathrm{d}v)}{\kappa_d} 
\end{align*}
\change{where whenever $\widehat{\varrho}$ is bimodal, $t\in[t_1,t_2)$, and both line sections
$L_{G_{s,\varrho_{\mathrm{app}}}\cap G^{(1)}_{t,\widehat{\varrho}}}(x,v)$ and $L_{G_{s,\varrho_{\mathrm{app}}}\cap G^{(2)}_{t,\widehat{\varrho}}}(x,v)$
are nonempty}
\begin{align*}
     \xi_{t,s}(x,v):=\frac{\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))}{\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))+\delta_{t,s}(x,v)} 

\end{align*}
\change{with}
\begin{align*}
      \delta_{t,s}(x,v)
  =\inf\bigl\{|z_1 - z_2|\;:\;
    z_1\in L_{G_{s,\varrho_{\mathrm{app}}}\cap G^{(1)}_{t,\widehat{\varrho}}}(x,v),\;
    z_2\in L_{G_{s,\varrho_{\mathrm{app}}}\cap G^{(2)}_{t,\widehat{\varrho}}}(x,v)
  \bigr\},
\end{align*}
\change{
and in all remaining cases, i.e., if $\widehat{\varrho}$ is unimodal, if $t\notin[t_1,t_2)$, or if at least one of the two line sections is empty, we set}
\[
    \xi_{t,s}(x,v):=1.
\]


\noindent \change{The $\pi_{0,t,s}$-reversibility of $R_{t,s}$ is a consequence of \cite[Lemma~4.10]{Rudolf2012} and of  \cite[Lemma~9]{LatuszynskiRudolf2024}, both viewed in the context of the delayed acceptance framework. Consequently by Proposition~\ref{prop:DAHSS:reversible}, the transition kernel of DA-HRUSS is reversible w.r.t. $\pi$.}  



In the following, let $x\in G$ and $A\in\mathcal{B}(G)$ be arbitrary. We \change{verify} for ergodicity Assumption \ref{statement1}. and \ref{statement2}. of Proposition \ref{prop:DAHSS:ergodic}. 
\begin{enumerate}

     \item If $\pi(A)>0$, an immediate consequence of Proposition~\ref{positive:measure:iff} is that there exist some $S_{x,A}\in(0, \rhoapp(x)]$ and $T_{x,A}\in(0, \widehat{\varrho}(x)]$, such that $\pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}) > 0$ for all $s\in(0, S_{x,A})$ and $t\in(0, T_{x,A})$. Following the approach in the proof of \cite[Lemma~11]{LatuszynskiRudolf2024} including using again \cite[Theorem~15.13]{Schilling2005}, we receive for (almost) all $s\in(0, S_{x,A})$ and (almost) all $t\in(0, T_{x,A})$
     \begin{align*}
      R_{t,s}(x,A)&\geq \int_{\mathbb{S}_{d-1}} \xi_{t,s}(x,v) \, \frac{\lambda_1(L_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))}  {\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v))}  \, \frac{\sigma_d(\mathrm{d}v)}{\kappa_d} \\ 
      & = \frac{2}{\kappa_d} \int_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}} \frac{\xi_{t,s}(x,\frac{x-y}{\|x-y\|})}{\|x-y\|^{d-1} \, \lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,\frac{x-y}{\|x-y\|}))}  \, \pi_0(\mathrm{d}y) \\
      & \change{= \frac{2}{\kappa_d} \int_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}} \frac{\pi_0(\mathrm{d}y)}{\|x-y\|^{d-1} \, (\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,\frac{x-y}{\|x-y\|}))+\delta_{t,s}(x, \frac{x-y}{\|x-y\|}))}} \\
      &\geq\frac{\change{2 \cdot }\ \pi_0(A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}})}{\kappa_d\cdot \underset{w_1,w_2\in G_{s,\varrho_{\textmd{app}}}}{\sup}\| w_1-w_2 \|^d}>0,
 \end{align*}
where the last inequality is due to 
\[
   \lambda_1\left(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}\left(x,\change{\frac{x-y}{\|x-y\|}}\right)\right)+\delta_{t,s}\left(x,\change{\frac{x-y}{\|x-y\|}}\right)\leq \underset{w_1,w_2\in G_{s,\varrho_{\textmd{app}}}}{\sup}\| w_1-w_2 \|. 
\]
\change{Furthermore, since $G_{s,\rhoapp}$ is bounded for all $s\in(0,\|\rhoapp\|_\infty)$ we have
\[
   \underset{w_1,w_2\in G_{s,\varrho_{\textmd{app}}}}{\sup}\| w_1-w_2 \|^d<\infty.
\]
}

    \item If $\pi(A)=0$, then also $\pi_0(A)=0$ by (\ref{PMLR:distribution}). Applying the formula in \citet[Theorem~15.13]{Schilling2005} yields
     \begin{align*}
       \int_{\mathbb{S}_{d-1}} \lambda_1(L_A(x,v)) \, \sigma_d(\mathrm{d}v)  
       & = \int_{\mathbb{S}_{d-1}} \int_{-\infty}^\infty \mathbb{1}_A(x+pv) \, \mathrm{d}p \, \sigma_d(\mathrm{d}v) \\
       & = 2 \int_A \frac{1}{\| x-y \|^{d-1}}\pi_0(\mathrm{d}y)=0.   
     \end{align*}
     Hence, we obtain $\lambda_1(L_A(x,v))=0$ for $\sigma_d$-almost every $v\in\mathbb{S}_{d-1}$, which immediately implies $R_{t,s}(x,A)=0$ for all $t\in(0,\widehat{\varrho}(x))$ and all $s\in(0, \rhoapp(x))$ \change{since $L_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(x,v)\subseteq L_A(x,v)$ and $L_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G^{(i)}_{t,\widehat{\varrho}}}(x,v))\subseteq L_A(x,v)$ for $i=1,2$.}

\end{enumerate}

\begin{flushright}    
$\square$
\end{flushright}

\label{app:DAGPSS}

The on-slice transition kernels of DA-GPSS for $x= r_0 \, \nu_0\in G$, $A\in\mathcal{B}(G)$, $s \in (0, \rhoapp(x))$ and $t \in (0, \widehat{\varrho}(x))$, \change{underlying Algorithm \ref{alg:DAGPSS}}, take the form $B_{t,s}(r_0 \, \nu_0,A)=B^{(D)}_{t,s}B^{(R)}_{t,s}(r_0 \, \nu_0,A)$ and are the compositions of the transition kernels of the direction update $B^{(D)}_{t,s}$ and the transition kernels of the radius update $B^{(R)}_{t,s}$, \change{where the latter is given due to Assumption \ref{assum:radius:update} by}






\[
   B^{(R)}_{t,s}(r_0\, v, A)=\frac{\lambda_1(L_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(v))}{\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(v))}  
\]
\change{with $L_{\cdot}(v)$ as defined in \eqref{segment:gpss}}.

\change{The arguments of \citet[Lemma~4.6, Theorem~4.13]{Schaer2025} can now be extended to the delayed acceptance version to establish the $\pi_{0,t,s}$-reversibility of the kernels $B^{(R)}_{t,s}$ and $B^{(D)}_{t,s}$. The $\pi_{0,t,s}$-invariance of $B_{t,s}$ follows then directly from}
\[
  \change{\pi_{0,t,s}B_{t,s}=\pi_{0,t,s}B^{(D)}_{t,s}B^{(R)}_{t,s}= \pi_{0,t,s}B^{(R)}_{t,s}=\pi_{0,t,s}.}
\]
\change{Hence, by Proposition~\ref{prop:DAHSS:reversible} the transition kernel of DA-GPSS is invariant w.r.t. $\pi$.} 

\change{Next, we verify the assumptions of Proposition \ref{prop:DAHSS:ergodic} to show ergodicity. To this end, let again $x= r_0 \, \nu_0\in G$, $s \in (0, \rhoapp(x))$ and $t \in (0, \widehat{\varrho}(x))$ be arbitrary. 
We follow similar steps as in \cite{SchaerEtAl2023} and obtain by Equation (4.20) in the proof of \cite[Theorem~4.14]{Schaer2025}}  

    \[
       B^{(D)}_{t,s}(r_0\, v_0, \mathrm{d}z) \geq \varepsilon \, \int_{\mathbb{S}_{d-1}} \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\, v) \, \delta_{r_0 \, v}(\mathrm{d}z) \, \sigma_d(\mathrm{d}v)
    \]
    for a $\varepsilon>0$, see the proof of \cite[Theorem~4.14]{Schaer2025} for the explicit definition of $\varepsilon$. Following the proof of \cite[Theorem~3.2]{SchaerEtAl2023} we analogously have
    \begin{align*}
        B_{t,s}(r_0\, v_0, A)&= \int_{ G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}} B^{(R)}_{t,s}(z, A) \, B^{(D)}_\change{{t,s}}(r_0\, v_0, \mathrm{d}z) \\
                           &\geq \varepsilon \, \int_{\mathbb{S}_{d-1}} \int_{ G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}}  B^{(R)}_{t,s}(z, A) \, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\, v) \, \delta_{r_0 \, v}(\mathrm{d}z) \, \sigma_d(\mathrm{d}v) \\
                           &= \varepsilon \, \int_{\mathbb{S}_{d-1}} B^{(R)}_{t,s}(r_0 \, v, A) \, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\, v) \, \sigma_d(\mathrm{d}v) \\ 
                           &= \varepsilon \, \int_{\mathbb{S}_{d-1}} \int_{0}^\infty  \frac{\mathbb{1}_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r\,v)}{\lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(v))} \, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\,v) \, \mathrm{d}r \, \sigma_d(\mathrm{d}v) \\
                           &= \varepsilon \, \int_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}} \frac{\mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\frac{y}{\|y\|})}{\|y\|^{d-1} \, \lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(\frac{y}{\|y\|}))} \, \mathrm{d}y,  
    \end{align*}
    where the last equality again results from \cite[Theorem~15.13]{Schilling2005}. 

    \change{Now, consider $A\in\mathcal B(G)$ with $\pi(A)>0$.} Then, due to Proposition~\ref{positive:measure:iff} there exist $S_{x,A}\in(0, \rhoapp(x)]$ and $T_{x,A}\in(0, \widehat{\varrho}(x)]$, such that $\pi_0(A\cap G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}) > 0$ for all $(s,t)\in(0, S_{x,A})\times(0, T_{x,A})$. 
    Let us define
    \begin{align*}
        F_\change{{s,t}}
        :=
        \left\{y \in A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}} \ \colon \ r_0\frac{y}{\|y\|} \in G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}} 
        \right\} 
    \end{align*}
    \change{for which we have, since $\pi(A)>0$, that}
    \begin{align*}
        \int^{T_{x,A}}_0 \int^{S_{x,A}}_0 \lambda_d(F_\change{{s,t}}) \, \mathrm{d}s \, \mathrm{d}t = &\int_A \left(\int^{S_{x,A}}_0 \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}}(y) \, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}}\left(r_0\frac{y}{\|y\|}\right) \, \mathrm{d}s\right) \\ 
        & \qquad \left(\int^{T_{x,A}}_0 \mathbb{1}_{G_{t, \widehat{\varrho}}}(y) \, \mathbb{1}_{G_{t, \widehat{\varrho}}}\left(r_0\frac{y}{\|y\|}\right) \, \mathrm{d}t\right) \, \mathrm{d}y >0,
    \end{align*}
    where the positivity for the second integral (third integral analogously) follows by 
    \begin{align*}
      \int^{S_{x,A}}_0 \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}}(y) \, \mathbb{1}_{G_{s,\varrho_{\textmd{app}}}}\left(r_0\frac{y}{\|y\|}\right) \, \mathrm{d}s = \min\left(S_{x,A}, \rhoapp(y), \rhoapp\left(r_0\frac{y}{\|y\|}\right)\right) >0.     
    \end{align*}
    \change{Hence, there exists $(\tilde{s},\tilde{t})\in(0,S_{x,A})\times(0,T_{x,A})$ such that
    $\lambda_d(F_{\tilde{s},\tilde{t}})>0$. 
    Since the superlevel sets of $\rhoapp$ and $\rhohat$ are nested, we have $F_{\tilde{s},\tilde{t}}\subseteq F_{s,t}$ whenever $s\leq \tilde{s}$ and $t\leq \tilde{t}$. Thus, by redefining $S_{x,A} := \tilde s$ and $T_{x,A}:= \tilde t$, we obtain $\lambda_d(F_{s,t})>0$ for all
    $(s,t)\in(0,S_{x,A})\times(0,T_{x,A})$.} Furthermore by using \cite[Lemma~\change{B}.4]{SchaerEtAl2023} in our setting, we can conclude 
    \[
    \lambda_1\left(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}\left(\frac{y}{\|y\|}\right)\right)<\infty
    \] 
    for $\lambda_1\otimes\lambda_1\otimes \lambda_d$-almost all $(s,t, y)\in(0, S_{x,A})\times (0, T_{x,A}) \times A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}$.
    Therefore, we receive for (almost) all $s\in(0, S_{x,A})$ and (almost) all $t\in(0, T_{x,A})$  
    \[
    B_{t,s}(r_0\, v_0, A)\geq \varepsilon \, \int_{A \cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}} \frac{\mathbb{1}_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(r_0\frac{y}{\|y\|})}{\|y\|^{d-1} \, \lambda_1(L_{G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(\frac{y}{\|y\|}))} \, \mathrm{d}y >0 
    \]
    \change{which verifies the first assumption of Proposition \ref{prop:DAHSS:ergodic}.}

\change{
If $\pi(A)=0$, then also $\pi_0(A)=0$ by \eqref{PMLR:distribution}. By \cite[Theorem~15.13]{Schilling2005} we have
\begin{align*}
    0 = \pi_0(A) = \int_{\mathbb{S}_{d-1}} \lambda_1(L_A(v)) \, \sigma_d(\mathrm{d}v)
\end{align*}
and therefore $\lambda_1(L_{A\cap G_{s,\varrho_{\textmd{app}}}\cap G_{t,\widehat{\varrho}}}(v))=0$ for $\sigma_d$-almost all $v$. This implies $B^{(R)}_{t,s}(r_0\, v, A)=0$ for $\sigma_d$-almost all $v$. 
Analogously to the direction update of GPSS in \cite[Theorem~4.11]{Schaer2025}, the direction kernel of DA-GPSS $B^{(D)}_{t,s}(r_0\, v_0,\cdot)$ is absolutely continuous with respect to $\sigma_d$ by the same arguments as for DA-ESS in the proof of Theorem \ref{theo:DAESS}. 
Hence, we obtain 
\begin{align*}
    B_{t,s}(r_0\, v_0, A)= \int_{ G_{s, \varrho_{\textmd{app}}}\cap G_{t, \widehat{\varrho}}} B^{(R)}_{t,s}(z, A) \, B^{(D)}_{t,s}(r_0\, v_0, \mathrm{d}z)=0
\end{align*}
for all $t\in(0,\widehat{\varrho}(x))$ and all $s\in(0, \rhoapp(x))$ which verifies the second assumption of Proposition \ref{prop:DAHSS:ergodic} and, thus, completes the proof. \hfill \qed









}






